import{_ as c,r as t,o as l,c as i,e,a as s,s as u,d as a}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"响应和视图 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"基本响应","slug":"基本响应","link":"#基本响应","children":[{"level":4,"title":"从 CMS 方法返回字符串","slug":"从-cms-方法返回字符串","link":"#从-cms-方法返回字符串","children":[]},{"level":4,"title":"从 AJAX 处理程序返回字符串","slug":"从-ajax-处理程序返回字符串","link":"#从-ajax-处理程序返回字符串","children":[]},{"level":4,"title":"从路由返回字符串","slug":"从路由返回字符串","link":"#从路由返回字符串","children":[]},{"level":4,"title":"创建自定义响应","slug":"创建自定义响应","link":"#创建自定义响应","children":[]},{"level":3,"title":"向响应附加标头","slug":"向响应附加标头","link":"#向响应附加标头","children":[]},{"level":3,"title":"向响应附加 Cookie","slug":"向响应附加-cookie","link":"#向响应附加-cookie","children":[]}]},{"level":2,"title":"其他响应类型","slug":"其他响应类型","link":"#其他响应类型","children":[{"level":3,"title":"视图响应","slug":"视图响应","link":"#视图响应","children":[]},{"level":3,"title":"JSON 响应","slug":"json-响应","link":"#json-响应","children":[]},{"level":3,"title":"文件下载","slug":"文件下载","link":"#文件下载","children":[{"level":4,"title":"流式下载","slug":"流式下载","link":"#流式下载","children":[]}]},{"level":3,"title":"文件响应","slug":"文件响应","link":"#文件响应","children":[]}]},{"level":2,"title":"重定向","slug":"重定向","link":"#重定向","children":[{"level":3,"title":"返回带有闪存数据的重定向","slug":"返回带有闪存数据的重定向","link":"#返回带有闪存数据的重定向","children":[{"level":4,"title":"重定向到上一个 URL","slug":"重定向到上一个-url","link":"#重定向到上一个-url","children":[]},{"level":4,"title":"重定向到当前页面","slug":"重定向到当前页面","link":"#重定向到当前页面","children":[]}]}]},{"level":2,"title":"响应宏","slug":"响应宏","link":"#响应宏","children":[]},{"level":2,"title":"视图","slug":"视图","link":"#视图","children":[{"level":4,"title":"向视图传递数据","slug":"向视图传递数据","link":"#向视图传递数据","children":[]},{"level":4,"title":"将子视图传递给视图","slug":"将子视图传递给视图","link":"#将子视图传递给视图","children":[]},{"level":4,"title":"确定视图是否存在","slug":"确定视图是否存在","link":"#确定视图是否存在","children":[]},{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/extend/services/response-view.md","filePath":"3.x/zh-cn/extend/services/response-view.md"}'),r={name:"3.x/zh-cn/extend/services/response-view.md"};function k(d,n,g,h,v,m){const p=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[e(p),n[0]||(n[0]=s("h1",null,"响应和视图",-1)),e(o),n[1]||(n[1]=u(`<h2 id="基本响应"><a href="#基本响应" class="header-anchor">#</a> 基本响应</h2><p>几乎所有页面使用的 PHP 方法都可以返回响应。这包括<a href="./../../cms/themes/layouts.html">布局执行生命周期</a>中包含的所有 CMS 方法和 <a href="./../../cms/ajax/handlers.html">AJAX 处理程序定义</a>。</p><h4 id="从-cms-方法返回字符串"><a href="#从-cms-方法返回字符串" class="header-anchor">#</a> 从 CMS 方法返回字符串</h4><p>从 CMS 页面、布局或组件方法返回字符串将在此处停止进程并覆盖默认行为，因此这里将显示 &quot;Hello World&quot; 字符串而不是显示页面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="从-ajax-处理程序返回字符串"><a href="#从-ajax-处理程序返回字符串" class="header-anchor">#</a> 从 AJAX 处理程序返回字符串</h4><p>从 AJAX 处理程序返回字符串将使用默认键 <code>result</code> 将字符串添加到响应集合中。请求的局部视图仍将包含在响应中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onDoSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
    <span class="token comment">// [&#39;result&#39; =&gt; &#39;Hello World&#39;]</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="从路由返回字符串"><a href="#从路由返回字符串" class="header-anchor">#</a> 从路由返回字符串</h4><p>从<a href="./../system/routing.html">路由定义</a>返回字符串将与 CMS 方法相同，将字符串显示为响应。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="创建自定义响应"><a href="#创建自定义响应" class="header-anchor">#</a> 创建自定义响应</h4><p>对于更强大的解决方案，返回一个 <code>Response</code> 对象，提供用于构建 HTTP 响应的各种方法。我们将在本文中进一步探讨此主题。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Page not found&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$statusCode</span> <span class="token operator">=</span> <span class="token number">404</span><span class="token punctuation">;</span>
<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$contents</span><span class="token punctuation">,</span> <span class="token variable">$statusCode</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="向响应附加标头"><a href="#向响应附加标头" class="header-anchor">#</a> 向响应附加标头</h3><p>请记住，大多数响应方法都是可链式调用的，允许流畅地构建响应。例如，你可以使用 <code>header</code> 方法在将响应发送回用户之前添加一系列标头：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-One&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-Two&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>一个实际的例子是返回 XML 响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$xmlString</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="向响应附加-cookie"><a href="#向响应附加-cookie" class="header-anchor">#</a> 向响应附加 Cookie</h3><p><code>withCookie</code> 方法允许你轻松地将 cookie 附加到响应。例如，你可以使用 withCookie 方法生成 cookie 并将其附加到响应实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>withCookie</code> 方法接受额外的可选参数，允许你进一步自定义 cookie 的属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">,</span> <span class="token variable">$path</span><span class="token punctuation">,</span> <span class="token variable">$domain</span><span class="token punctuation">,</span> <span class="token variable">$secure</span><span class="token punctuation">,</span> <span class="token variable">$httpOnly</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="其他响应类型"><a href="#其他响应类型" class="header-anchor">#</a> 其他响应类型</h2><p><code>Response</code> 门面可用于便捷地生成其他类型的响应实例。</p><h3 id="视图响应"><a href="#视图响应" class="header-anchor">#</a> 视图响应</h3><p>如果你需要访问 <code>Response</code> 类方法，但希望返回视图作为响应内容，你可以使用 <code>Response::view</code> 方法以方便使用：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">view</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::hello&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="json-响应"><a href="#json-响应" class="header-anchor">#</a> JSON 响应</h3><p><code>json</code> 方法将自动将 <code>Content-Type</code> 标头设置为 application/json，并使用 <code>json_encode</code> PHP 函数将给定的数组转换为 JSON：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果你想创建 JSONP 响应，可以使用 <code>json</code> 方法并结合 <code>setCallback</code>：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">setCallback</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;callback&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="文件下载"><a href="#文件下载" class="header-anchor">#</a> 文件下载</h3><p><code>download</code> 方法可用于生成强制用户浏览器在给定路径（第一个参数）下载文件的响应。<code>download</code> 方法可选地接受文件名（第二个参数，将决定用户下载文件时看到的文件名）和一个 HTTP 标头数组（第三个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">deleteFileAfterSend</span><span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Symfony HttpFoundation 管理文件下载，要求下载的文件具有 ASCII 文件名。</p></div><h4 id="流式下载"><a href="#流式下载" class="header-anchor">#</a> 流式下载</h4><p>在某些情况下，你可能希望将字符串响应转换为可下载的响应，而不必将内容写入磁盘。使用 <code>streamDownload</code> 方法来解决此问题，该方法接受回调（第一个参数）、文件名（第二个参数）和可选的标头数组（第三个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">streamDownload</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;CSV Contents...&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;export.csv&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="文件响应"><a href="#文件响应" class="header-anchor">#</a> 文件响应</h3><p><code>file</code> 方法用于直接在用户浏览器中显示文件（如图片或 PDF），而不是启动下载。此方法接受文件路径（第一个参数）和标头数组（第二个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="重定向"><a href="#重定向" class="header-anchor">#</a> 重定向</h2><p>重定向响应通常是 <code>Illuminate\\Http\\RedirectResponse</code> 类的实例，包含将用户重定向到另一个 URL 所需的正确标头。生成 <code>RedirectResponse</code> 实例的最简单方法是使用 <code>Redirect</code> 门面上的 <code>to</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="返回带有闪存数据的重定向"><a href="#返回带有闪存数据的重定向" class="header-anchor">#</a> 返回带有闪存数据的重定向</h3><p>重定向到新 URL 和<a href="./session.html">将数据闪存到 session</a> 通常同时进行。因此，为了方便，你可以创建 <code>RedirectResponse</code> 实例并在单个方法链中将数据闪存到 session：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;message&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Login Failed&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>由于 <code>with</code> 方法将数据闪存到 session，你可以使用典型的 <code>Session::get</code> 方法检索数据。</p></div><h4 id="重定向到上一个-url"><a href="#重定向到上一个-url" class="header-anchor">#</a> 重定向到上一个 URL</h4><p>你可能希望将用户重定向到他们之前的位置，例如在提交表单后。你可以使用 <code>back</code> 方法来实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withInput</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="重定向到当前页面"><a href="#重定向到当前页面" class="header-anchor">#</a> 重定向到当前页面</h4><p>有时你只想简单地刷新当前页面，你可以使用 <code>refresh</code> 方法来实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="响应宏"><a href="#响应宏" class="header-anchor">#</a> 响应宏</h2><p>如果你想定义一个可以在多个路由和控制器中重复使用的自定义响应，可以使用 <code>Response::macro</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">macro</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;caps&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>macro</code> 函数接受名称作为第一个参数，闭包作为第二个参数。宏的闭包将在 <code>Response</code> 类上调用宏名称时执行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">caps</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>你可以在<a href="./../extending.html">插件注册文件</a>的 <code>boot</code> 方法中定义宏。另外，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，用于放置宏注册。</p><h2 id="视图"><a href="#视图" class="header-anchor">#</a> 视图</h2><p>视图是存储基于系统的表示逻辑的好方法，例如 API 或端点使用的标记，或 CMS 和后台区域共享的标记。视图也被<a href="./../system/sending-mail.html">邮件服务</a>用于提供默认模板内容。视图通常存储在插件的 <code>views</code> 目录中。</p><p>一个简单的视图可能如下所示：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.htm --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>视图也可以使用 <code>.php</code> 扩展名通过 PHP 模板进行解析：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.php --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>此视图可以使用 <code>View::make</code> 方法返回到浏览器：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Charlie&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第一个参数是&quot;路径提示&quot;，包含插件名称，用两个冒号 <code>::</code> 分隔，后面跟着视图文件名。第二个参数传递给 <code>View::make</code> 的是应该提供给视图的数据数组。</p><div class="custom-block tip"><p>路径提示区分大小写，插件名称应始终为小写。</p></div><h4 id="向视图传递数据"><a href="#向视图传递数据" class="header-anchor">#</a> 向视图传递数据</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 使用常规方法</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 使用魔术方法</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在上面的示例中，变量 <code>name</code> 可以从视图中访问，并且将包含 <code>Steve</code>。如上所述，如果你想传递一个数据数组，可以将其作为第二个参数传递给 <code>make</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>也可以在所有视图之间共享一段数据：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="将子视图传递给视图"><a href="#将子视图传递给视图" class="header-anchor">#</a> 将子视图传递给视图</h4><p>有时你可能希望将一个视图传递到另一个视图中。例如，给定一个存储在 <code>plugins/acme/blog/views/child/view.php</code> 的子视图，我们可以这样将其传递给另一个视图：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>子视图然后可以从父视图中渲染：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="确定视图是否存在"><a href="#确定视图是否存在" class="header-anchor">#</a> 确定视图是否存在</h4><p>如果你需要检查视图是否存在，请使用 <code>View::exists</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.customer&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4>`,88)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"./../../cms/features/upload-download.html"},"上传和下载")]),s("li",null,[s("a",{href:"https://laravel.com/docs/10.x/responses",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel 响应"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const x=c(r,[["render",k]]);export{w as __pageData,x as default};
